INSERT INTO `vacancies` (`id`, `hh_id`, `title`, `company`, `salary`, `url`, `cover_letter`, `status`, `created_at`) VALUES
(9, '129652004', 'Fullstack JS developer (Junior+)', 'ЮМАСОФТ', NULL, 'https://rabota.by/vacancy/129652004', 'Как опытный Frontend-разработчик с опытом работы в стеке Vue 3, Node.js, JS, TS, Nuxt.js и MongoDB, я уверен в своей способности внести значительный вклад в вашу команду. Мой опыт работы с фреймворками и технологиями, перечисленными в требованиях, а также мои знания принципов проектирования RESTful API и опыт создания масштабируемых backend-сервисов и API, делают меня сильным кандидатом на эту позицию. Я готов работать над реальными продуктами, улучшать свои навыки общения на английском языке и расти в профессиональной среде.', 'applied', '2026-02-05 10:03:12'),
(10, '129193322', 'Shopify Senior Developer (JavaScript&Liquid&OOPL)', 'Itransition', NULL, 'https://rabota.by/vacancy/129193322', 'Хотя мой основной стек — Vue 3, Node.js, JS, TS, Nuxt.js и MongoDB, я уверен, что могу быстро освоить Liquid и другие технологии, необходимые для работы с Shopify. С более чем 4-летним опытом в frontend-разработке и сильными навыками коммуникации, я готов присоединиться к вашей команде и внести свой вклад в инновационные решения электронной коммерции. Мне интересно работать с такими известными клиентами, как PayPal и adidas, и я ценю предложенные условия, включая гибкий график, оплату медицинских расходов и возможности карьерного роста.', 'applied', '2026-02-05 10:03:58'),
(12, '129600290', 'Frontend-разработчик', 'ООО АвтоБНП', NULL, 'https://rabota.by/vacancy/129600290', 'Я - разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js и MongoDB. Однако, я готов изучить React и поработать над созданием современной e-commerce платформы. Мой опыт работы с frontend-разработкой и знание принципов работы с REST API могут быть полезны для вашего проекта. Я готов учиться и развиваться, и мне интересно работать над коммерческим продуктом. Отправляю свое резюме и готов пройти техническое собеседование.', 'applied', '2026-02-05 10:05:03'),
(13, '129995584', 'Middle+ / Senior Full-stack developer (Node.js + React)', 'ООО УайтСнейк', NULL, 'https://rabota.by/vacancy/129995584', 'Хотя моя основная специализация — разработка frontend-приложений на Vue 3, Nuxt.js, я также имею опыт работы с Node.js, JavaScript, TypeScript и MongoDB. Меня привлекает возможность работать с передовыми технологиями и инновационными решениями в компании WhiteSnake. Я готов расширить свои навыки и изучить React, чтобы соответствовать требованиям вакансии. Мои знания в области разработки frontend и опыт работы с серверной частью могут быть ценными в вашей команде. Я заинтересован в обсуждении моей кандидатуры и изучении возможностей роста в вашей компании.', 'applied', '2026-02-05 10:05:44'),
(15, '130035685', 'Middle Back-End Developer', 'ООО Дримтим Аппс', NULL, 'https://rabota.by/vacancy/130035685', 'Хотя мой основной стек - Frontend (Vue 3, Nuxt.js), у меня есть опыт работы с Node.js, TypeScript и MongoDB. Однако, кажется, что вакансия требует специалиста в области Back-end разработки, поэтому я не совсем подхожу под требования. Тем не менее, я готов изучить и освоить новые технологии и инструменты, такие как TSOA, Nest.js и Firebase Firestore, чтобы стать частью вашей команды. Если вы открыты к обучению и развитию сотрудников, я готов обсудить возможность работы вместе.', 'applied', '2026-02-05 10:06:47'),
(16, '129931293', 'Mid Frontend Developer - NXTY', 'ООО ФОРТВИЖН', NULL, 'https://rabota.by/vacancy/129931293', 'Хотя мой основной стек включает Vue 3, Node.js, JS, TS, Nuxt.js и MongoDB, я уверен, что мои навыки в frontend-разработке и опыт работы с сложными интерфейсами могут быть адаптированы для работы с React и другими технологиями, указанными в вакансии. Я готов изучить и освоить новые технологии, включая React и Tailwind CSS, чтобы соответствовать требованиям вакансии. Мой опыт в создании pixel-perfect UI, работе с CSS и layout, а также опытом в построении чистых и масштабируемых UI-компонентов могут быть полезными для вашей команды. Я также готов тесно взаимодействовать с дизайнерами и продакт-менеджерами, чтобы обеспечить высокое качество интерфейсов. Я считаю, что мой инженерный подход и внимание к деталям могут быть ценными активами для вашей команды.', 'applied', '2026-02-05 10:07:33'),
(17, '129464774', 'Frontend-разработчик', 'ООО Евроторг', NULL, 'https://rabota.by/vacancy/129464774', 'Как опытный frontend-разработчик с опытом работы более 3 лет, я уверен в своих навыках работы с современными технологиями. Мой стек включает Vue 3, Node.js, JS, TS, Nuxt.js и MongoDB. Я готов принять участие в разработке и сопровождении проектов группы компаний ООО «Евроторг» и внедрить новые архитектурные решения. Я знаком с принципами модульной вёрстки (БЭМ) и имею опыт работы с API REST, Docker и Git. Я также имею навыки Unit-тестирования и понимаю принципы UX. Я готов присоединиться к вашей команде и внести свой вклад в успех компании.', 'applied', '2026-02-05 10:08:36'),
(18, '129219095', 'Frontend-разработчик (Next.js)', 'Холдинг Аптека групп (сеть аптек ADEL и Добрыя лекi)', NULL, 'https://rabota.by/vacancy/129219095', 'Хотя мой основной стек — Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, я заинтересован в изучении и работе с Next.js. Опыт работы с JavaScript, TypeScript и React позволит мне быстро адаптироваться к новой технологии. Готов обсудить возможность трудоустройства и дальнейшего обучения для соответствия требованиям вакансии.', 'applied', '2026-02-05 10:09:24'),
(24, '130174983', 'Golang developer', 'ООО Секьюрити Лаб', NULL, 'https://rabota.by/vacancy/130174983', 'К сожалению, моя квалификация не соответствует требованиям вакансии. Мой опыт и навыки лежат в области frontend-разработки (Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB), а не в backend-разработке на Golang. Желаю удачи в поисках подходящего кандидата!', 'applied', '2026-02-05 10:11:15'),
(29, '129977851', 'QA Automation Engineer (Middle)', 'ООО Кэтлоджик', NULL, 'https://rabota.by/vacancy/129977851', 'Имею 3 года коммерческого опыта на Node.js/TypeScript и 2 года в автоматическом тестировании. Разрабатывал фреймворки на Node.js, тесты с Cypress/Playwright, интегрировал MySQL. Успешно сокращал технический долг и участвовал в code review. Опыт фронтенд-разработки на Vue 3 позволяет глубже понимать архитектуру продуктов. Уверенно читаю англоязычную документацию и работал в тесном взаимодействии с командами тестировщиков. Готов к удалённой работе и гибкому графику.', 'applied', '2026-02-05 18:27:23'),
(35, '129700567', 'Системный архитектор', 'ОАО НКФО «ЕРИП»', NULL, 'https://rabota.by/vacancy/129700567', 'Владею стеком Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL. Опыт разработки высоконагруженных систем более 4 лет, включая финтех-проекты. Умею проектировать масштабируемые архитектуры и контролировать качество разработки. Готов взять на себя ответственность за архитектуру и развитие команды. Ищу сложные задачи, где можно применить креатив и опыт. Заинтересован в вакансии и готов обсудить детали.', 'applied', '2026-02-05 18:41:04'),
(36, '129891647', 'Frontend-разработчик / HTML-верстальщик', 'Медиа Лайн', NULL, 'https://rabota.by/vacancy/129891647', 'Имею 2+ года опыта в frontend-разработке с использованием Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL. Готов поделиться примерами выполненных работ и обсудить возможность сотрудничества.', 'applied', '2026-02-05 18:46:43'),
(37, '130162599', 'Svelte Support Developer', 'Andersen', NULL, 'https://rabota.by/vacancy/130162599', 'Как Frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я заинтересован в вакансии Svelte Support Developer. Однако, я хотел бы отметить, что мой основной стек технологий отличается от требуемого, но я уверен, что мой опыт и навыки могут быть адаптированы для работы с Svelte. Я готов учиться и развиваться, и считаю, что моя способность быстро осваивать новые технологии и решать сложные проблемы будет полезна для вашей команды. Я также ценю возможность работать с лидерами в FinTech, Healthcare, Retail, Telecom и других отраслях, а также перспективы профессионального и карьерного роста.', 'applied', '2026-02-05 18:50:57'),
(38, '129926116', 'Fullstack Developer', 'ООО Апро Интеллект', NULL, 'https://rabota.by/vacancy/129926116', 'Владею Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL. Опыт работы с frontend-разработкой более 4 лет. Имею сильные знания JavaScript, Vue.js и HTML5 Canvas 2D. Готов расширить алгоритм для подбора схем подогрева пола и реализовать его с помощью JavaScript и Vue.js. Знаком с математическими концепциями, включая геометрию и координатные системы. Готов приступить к работе над проектом и адаптировать существующие шаблоны к полигональным формам комнат. Английский язык - B2+. Готов обсудить детали проекта и свою кандидатуру.', 'applied', '2026-02-05 18:53:05'),
(39, '122696959', '.NET Developer (со знанием немецкого языка)', 'Team.Inno / Фабрика инноваций и решений', NULL, 'https://rabota.by/vacancy/122696959', 'Как frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я заинтересован в вакансии в Team.Inno. Однако, я заметил, что основные требования включают опыт работы с .NET и backend-технологиями. Хотя мой основной стек технологий отличается, я готов изучать и расширять свои навыки в новых направлениях. Я считаю, что моя опыт и знания в frontend-разработке могут быть полезны в проектах компании, и я готов обсудить возможность присоединения к команде и изучения новых технологий.', 'applied', '2026-02-05 18:54:11'),
(41, '126117340', '.NET Developer', 'Team.Inno / Фабрика инноваций и решений', NULL, 'https://rabota.by/vacancy/126117340', 'К сожалению, моя квалификация не соответствует описанию вакансии .NET Developer (с AI-экспертизой), поскольку мой основной стек технологий включает Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL. Однако я готов изучать новые технологии и расширять свои знания. Если в компании есть возможность переквалификации или обучения, я был бы заинтересован в обсуждении возможностей работы в вашей команде.', 'applied', '2026-02-05 18:55:44'),
(42, '130141599', 'AQA Engineer (С#)', 'ООО ИнтэксСофт', NULL, 'https://rabota.by/vacancy/130141599', 'Как Frontend-разработчик с опытом в Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я не соответствую требованиям вакансии Automation QA Engineer (C#). Однако, если бы я был кандидатом на эту позицию, я бы написал сопроводительное письмо примерно так:\n\n\"Опытный Automation QA Engineer с опытом ручного тестирования и автоматизации тестирования на C#. Обеспечил WEB-тестирование различных платформ, включая банковские системы. Умею создавать тест-кейсы, работать с API, SOAP, REST, SQL. Имею понимание клиент-серверной архитектуры и практический опыт тест-дизайна. Готов применить свои навыки для обеспечения высокого качества банковской платформы.\"', 'applied', '2026-02-05 18:56:35'),
(46, '122637829', '.NET Developer (со знанием итальянского языка)', 'Team.Inno / Фабрика инноваций и решений', NULL, 'https://rabota.by/vacancy/122637829', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я заинтересован в вакансии в Team.Inno. Однако, я заметил, что основные ожидания вакансии ориентированы на опыт в написании .NET приложений и других технологий, не соответствующих моему стеку. \n\nЯ хотел бы обсудить возможность присоединения к команде в качестве Frontend-разработчика и изучить возможности применения моих навыков в проектах компании. Готов обсудить детали и возможности роста в компании.', 'applied', '2026-02-05 19:04:32'),
(49, '129935863', 'Lead Full Stack Developer (React+Node.js)', 'Andersen', NULL, 'https://rabota.by/vacancy/129935863', 'Хотя моя основная специализация - Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL, я уверен, что мой опыт и навыки могут быть адаптированы для работы с React+Node.js. Мне интересна возможность руководить командой разработчиков и участвовать в создании современной платформы электронной коммерции для продажи подержанных транспортных средств. Опыт работы с различными технологиями и навыки решения сложных технических задач позволят мне внести значительный вклад в проект. Кроме того, возможность профессионального роста, гибкие условия работы и привлекательные бонусы делают эту вакансию особенно привлекательной. Я готов обсудить детали и возможности адаптации моих навыков для проекта.', 'applied', '2026-02-05 19:08:33'),
(52, '127514316', 'Front-end разработчик (Nuxt)', 'ООО МАКСБИТСОЛЮШЕН', NULL, 'https://rabota.by/vacancy/127514316', 'Как опытный Frontend-разработчик с опытом работы в Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я уверен в своей способности эффективно мигрировать проекты на Nuxt 3, настраивать сборщики Webpack и Vite, а также обеспечивать производительность и безопасность разрабатываемых приложений. Готов поделиться знаниями и опытом с командой и участвовать в разработке новых решений. Заинтересован в перспективе роста и развития в компании.', 'applied', '2026-02-05 19:13:12'),
(53, '129632875', 'Frontend Developer (BI/Visualization)', 'ООО КлеверДев Софтваре', NULL, 'https://rabota.by/vacancy/129632875', 'Имею опыт работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL. Готов применить свои навыки в разработке аналитических веб-интерфейсов и дашбордов. Интересно работать с визуализацией данных и созданием интерактивных веб-приложений. Готов изучить Python и другие необходимые технологии. Ищу возможности профессионального роста и готов стать частью вашей команды.', 'applied', '2026-02-05 19:13:48'),
(57, '129704799', 'Junior Java Developer (Laboratory 2.0)', 'IDF Technology', NULL, 'https://rabota.by/vacancy/129704799', 'Как Frontend-разработчик с опытом работы со стеком Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL, я заинтересован в вакансии Laboratory 2.0 в IDF Technology. Однако, заметил, что вакансия требует опыта работы с Java, что не соответствует моему текущему стеку технологий. Если есть возможность рассмотреть кандидата с другим стеком технологий или возможность обучения и перехода на Java, я был бы рад обсудить детали вакансии и возможности роста в компании.', 'applied', '2026-02-05 19:22:19'),
(60, '130229401', 'QA Engineer Automation (web: TS, Playwright or mobile: Java)', 'Альфа-Банк: IT-направление и цифровой бизнес', NULL, 'https://rabota.by/vacancy/130229401', 'Как опытный Frontend-разработчик с опытом работы в стеке Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL, я уверен, что могу внести значительный вклад в команду Альфа Банка. Мой опыт работы с REST API, JSON и опыт тестирования web-приложений будут полезны для выполнения задач по тестированию и сопровождению компонентов процессинга и Fraud-системы. Я готов работать с распределенной командой разработки и участвовать в процессе поиска и разбора дефектов.', 'applied', '2026-02-06 11:12:50'),
(61, '129747773', 'Full- Stack (Angular + Java) Developer', 'ООО ИнтэксСофт', NULL, 'https://rabota.by/vacancy/129747773', 'К сожалению, мой технологический стек не соответствует требованиям вакансии. Мой опыт основан на Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, что отличается от необходимого опыта работы с Angular и Java. Поэтому я не смогу претендовать на эту вакансию.', 'applied', '2026-02-06 11:20:45'),
(62, '128572897', 'Middle Node Developer', 'Team.Inno / Фабрика инноваций и решений', NULL, 'https://rabota.by/vacancy/128572897', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я уверен в своей способности внести ценный вклад в проекты Team.Inno. Мой стек технологий соответствует требованиям вакансии, и я готов применить свои навыки на практике. Я заинтересован в возможности работать над разнообразными проектами и расти вместе с компанией.', 'applied', '2026-02-06 11:28:18'),
(64, '129266913', 'UI / UX designer', 'ООО МАКСБИТСОЛЮШЕН', NULL, 'https://rabota.by/vacancy/129266913', 'Как frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я заинтересован в возможности присоединиться к вашей команде в качестве UI/UX-дизайнера. Хотя моя основная специализация - разработка, у меня есть опыт работы с дизайном и желание расширить свои навыки в этой области. Я готов пройти тестовое задание и продемонстрировать свои способности.', 'applied', '2026-02-06 11:33:26'),
(66, '130069506', 'Frontend Developer', 'ЗАО Уайт Бёрд', NULL, 'https://rabota.by/vacancy/130069506', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я уверен, что могу внести свой вклад в развитие вашей криптоплатформы. Мои навыки в разработке удобных и интуитивно понятных интерфейсов, а также опыт оптимизации производительности и обеспечения кросс-браузерной совместимости, соответствуют требованиям вашей вакансии. Я готов участвовать в улучшении UX и взаимодействовать с командой backend-разработки и дизайнеров. Хотя у меня нет прямого опыта работы с React, я уверен, что могу быстро адаптироваться и применить свои знания в новом контексте. Готов обсудить возможность работы в вашей команде.', 'applied', '2026-02-06 11:38:06'),
(67, '129811945', 'PHP-программист (Bitrix24)', 'ООО Мератех', NULL, 'https://rabota.by/vacancy/129811945', 'К сожалению, моя специализация как Frontend-разработчика не соответствует требованиям вакансии PHP-программиста. Мой стек технологий включает Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL. Я бы с удовольствием рассмотрел другие возможности, соответствующие моим навыкам.', 'applied', '2026-02-06 11:42:09'),
(68, '130469833', 'Frontend-разработчик (Middle, Middle +)', 'ООО Спортдата', NULL, 'https://rabota.by/vacancy/130469833', 'Опытный Frontend-разработчик с опытом работы более 1 года. Знаком с JavaScript, TypeScript, SOLID, KISS. Умею писать чистый и поддерживаемый код. Опыт работы с Vue 3, Node.js, Nuxt.js, MongoDB, PostgreSQL. Готов присоединиться к динамическому проекту и расти как специалист. Портфолио: [ссылка на портфолио]. Жду обсуждения деталей.', 'applied', '2026-02-16 10:51:31'),
(69, '129388991', 'Senior UI/UX Designer в Дизайн-систему', 'ООО АйрисДев', NULL, 'https://rabota.by/vacancy/129388991', 'Как frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я заинтересован в вакансии UI/UX дизайнера в компании \"АйрисДев\". Однако, я хотел бы отметить, что моя основная специализация - frontend-разработка, а не дизайн. \n\nЕсли в компании есть возможность применения моих навыков в frontend-разработке, я был бы рад обсудить возможность работы в команде. Моя зарплатная ожидание составляет от 150 000 руб. в месяц.', 'applied', '2026-02-16 10:57:54'),
(72, '130474318', 'Junior Python Developer в Минске', 'ООО Финсельват', NULL, 'https://rabota.by/vacancy/130474318', 'Как frontend-разработчик со стеком Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB, PostgreSQL, я заинтересован в возможностях роста и развития в backend-разработке. Однако, мое основное направление — frontend, и я не уверен, что готов полностью переключиться на backend. Но я готов учиться и развиваться в смежных технологиях, включая Python и C#. Мой опыт работы с JavaScript и фронтенд-фреймворками может быть полезен при доработке фронтенд-логики. Я готов обсудить возможности и перспективы работы в вашей команде.', 'applied', '2026-02-16 11:11:05'),
(115, '132167042', 'Frontend-разработчик', 'ООО Спортдата', NULL, 'https://rabota.by/vacancy/132167042', 'Опытный Frontend-разработчик с 3+ летами опыта работы над реальными проектами. Знаком с JavaScript, TypeScript, Vue 3, Node.js, Nuxt.js, MongoDB и PostgreSQL. Понимаю принципы SOLID и KISS, пишу чистый и поддерживаемый код. Готов работать над крупными проектами и расти как специалист. Портфолио: [ссылка на портфолио].', 'applied', '2026-05-01 20:55:43'),
(116, '132041493', 'Front-end Developer', 'ООО Егоров Эдженси', NULL, 'https://rabota.by/vacancy/132041493', 'Хотя у меня основной опыт с Vue 3, Nuxt.js и TypeScript, я уверен, что мои навыки могут быть адаптированы для работы с React. Опыт работы с Node.js, MongoDB и PostgreSQL также может быть полезен в backend-разработке. Хочу отметить, что у меня нет прямого опыта с Web3-проектами, но я готов изучать и развиваться в этой сфере. Интерес к блокчейну и Web3-технологиям есть, и я готов принять участие в разработке Web3-функциональности. Готов обсудить возможность работы и мои перспективы в вашей команде.', 'applied', '2026-05-01 21:03:02'),
(119, '132572879', 'UI/UX designer', 'ООО МАКСБИТСОЛЮШЕН', NULL, 'https://rabota.by/vacancy/132572879', 'Как frontend-разработчик с опытом работы с Vue 3, Node.js, JS, TS, Nuxt.js, MongoDB и PostgreSQL, я заинтересован в вакансии UI/UX-дизайнера в MAXBITSOLUTION. Однако, я хотел бы отметить, что моя основная специализация - frontend-разработка, а не дизайн. Но я готов расширить свои навыки и изучить новые области, включая UI/UX-дизайн. Мой опыт работы с frontend-фреймворками и библиотеками может быть полезен в создании высоконагруженных систем и прототипировании интерфейсов. Я готов пройти тестовое задание и обсудить возможность моего участия в проекте.', 'applied', '2026-05-01 21:16:02'),
(120, '130686663', 'Senior frontend developer React AI-native / AI-native JS React Разработчик', 'Novakid Inc', NULL, 'https://hh.ru/vacancy/130686663', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я уверен в своей способности внести вклад в разработку высококачественных пользовательских интерфейсов для онлайн-платформы Novakid. Мои знания современных веб-технологий, включая HTML, CSS3 и адаптивный дизайн, позволят мне эффективно работать над оптимизацией компонентов и обеспечением максимальной производительности на различных устройствах и браузерах. Я готов применить свои навыки для создания инновационных и удобных интерфейсов для детей и учителей, и внести свой вклад в революцию онлайн-обучения.', 'applied', '2026-05-01 21:18:55'),
(121, '131889799', 'Fullstack-разработчик', 'ООО Фараон-трейд', NULL, 'https://rabota.by/vacancy/131889799', 'Могу предложить свои услуги как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js. Однако, заметил, что вакансия требует опыта работы с PHP и Laravel, а также 1С-Битрикс, что не входит в мой основной стек. Готов обсудить возможность обучения или сотрудничества с backend-разработчиком для выполнения задач. Могу взяться за frontend-часть проекта, включая кроссбраузерную и адаптивную верстку, работу с JavaScript, React и Vue.js.', 'applied', '2026-05-01 21:22:50'),
(122, '130978078', 'Разработчик .NET', 'Т-Банк. ИТ. Разработка', NULL, 'https://hh.ru/vacancy/130978078', 'Как frontend-разработчик со стеком Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я заинтересован в возможности работать в компании, где есть высокая культура разработки и минимум Legacy-кода. Однако, я заметил, что вакансия требует опыта работы с .NET, который не входит в мой текущий стек. \n\nЯ готов изучить новые технологии и расширить свои знания, но хотел бы обсудить возможность обучения и адаптации к новой технологической среде. Мои навыки в области frontend-разработки и опыт работы с JavaScript и TypeScript могут быть полезны в компании, и я готов принять участие в разработке сервисов и проектов. \n\nЯ ценю возможность профессионального роста и развития, а также гибридный формат работы и достойную зарплату. Я был бы рад обсудить возможность работы в компании и изучить возможность адаптации к новой технологической среде.', 'applied', '2026-05-01 21:31:36'),
(123, '132001909', 'QA-инженер (финтех / крипто)', 'ЗАО Уайт Бёрд', NULL, 'https://rabota.by/vacancy/132001909', 'Как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии QA-инженера в WhiteBird. Мой опыт работы с frontend-технологиями позволяет мне понимать взаимодействие backend и frontend, а также имею базовые знания SQL и опыт работы с СУБД. Я готов изучить и применить на практике техники тест-дизайна и работать с Postman, Swagger и DevTools. Меня привлекает перспектива работы над масштабным живым продуктом в сфере финтех и криптовалют, а также современный офис и доброжелательная атмосфера. Готов пройти тестовое задание и онлайн-собеседование.', 'applied', '2026-05-01 21:52:18'),
(124, '131829289', 'VIP Account Manager', 'ООО ЭфЭлЭс Компани', NULL, 'https://rabota.by/vacancy/131829289', 'К сожалению, вакансия не соответствует моей профессии Frontend-разработчика. Я имею опыт работы со стеком Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, но эта вакансия требует опыта в сфере iGaming и поддержки VIP-клиентов.', 'applied', '2026-05-01 22:01:26'),
(125, '131714391', 'PHP Middle+/Senior Developer', 'Itransition', NULL, 'https://rabota.by/vacancy/131714391', 'Хотя мой основной стек — Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я готов изучить PHP и Laravel, чтобы решать сложные технические задачи и разрабатывать высококачественные системы. Опыт работы с RESTful API, Git и Agile-методологиями. Готов учиться и расти в компании.', 'applied', '2026-05-01 22:03:22'),
(126, '132174906', 'Frontend Developer (Мир Танков)', 'Леста Игры', NULL, 'https://hh.ru/vacancy/132174906', 'Как опытный Frontend-разработчик с опытом работы более 3-х лет, я уверен в своих способностях разрабатывать и совершенствовать существующие мета-системы игры и веб-сервисов. Мой стек включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL. Я готов внести свой вклад в вашу команду и работать с актуальными технологиями, внедряя передовые подходы в разработке игр. Готов к код-ревью и решению инцидентов. Интересуюсь предложением вашей компании и готов обсудить детали.', 'applied', '2026-05-01 22:08:06'),
(127, '132547045', 'Manual QA Engineer', 'ООО Дигитеум', NULL, 'https://rabota.by/vacancy/132547045', 'Как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в перспективе создания и размещения вакансии Manual QA Engineer в Digiteum. Однако, моя основная экспертиза лежит в области frontend-разработки, а не тестирования. Если у вас есть возможность рассмотреть кандидата с моими навыками для другой роли, я был бы рад обсудить возможности.', 'applied', '2026-05-01 22:16:59'),
(128, '132675536', 'QA Engineer Web3 (Manual + Automation)', 'Holiverse', NULL, 'https://hh.ru/vacancy/132675536', 'Как Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии QA Engineer (Manual + Automation) в вашей компании. Однако, я хотел бы отметить, что моя основная специализация - frontend-разработка, и у меня нет прямого опыта в QA.\n\nТем не менее, я уверен, что мои навыки в области frontend-разработки и знание технологий, таких как Node.js, JS и TS, могут быть полезными в тестировании и автоматизации тестирования. Кроме того, я готов учиться и развивать новые навыки, включая опыт работы с Web3-проектами и автоматизацией тестирования.\n\nЯ бы хотел обсудить возможность участия в вашей команде и изучить, как мои навыки могут быть применены к вакансии QA Engineer.', 'applied', '2026-05-01 22:25:39'),
(129, '131880524', 'FullSTack Tech Lead', 'ЗАО Пиксель Интернет', NULL, 'https://rabota.by/vacancy/131880524', 'Как опытный Frontend-разработчик с опытом работы в стэке Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я уверен в своей способности возглавить развитие вашей Fintech-экосистемы. Мой опыт работы с высоконагруженными системами и масштабируемыми архитектурами позволит мне обеспечить высокое качество кода и руководить командой разработчиков. Я готов применить свои знания в области Cloudflare Workers и Edge Runtime для создания быстрых интерфейсов и обеспечить техническую экспертизу в области функционирования торговой системы. Готов обсудить детали и присоединиться к вашей команде.', 'applied', '2026-05-01 22:32:10'),
(131, '132475867', 'Frontend-разработчик', 'ООО Кэтлоджик', NULL, 'https://rabota.by/vacancy/132475867', 'Имею опыт создания адаптивных интерфейсов с использованием Vue 3, React, Node.js, TypeScript и JavaScript. Умею работать с REST API, MongoDB и PostgreSQL. Понимаю принципы адаптивного дизайна и UI/UX. Опыт работы с Git и системами управления задачами. Английский язык - B1. Готов к удалённой работе и сотрудничеству в международной команде.', 'applied', '2026-05-01 22:39:00'),
(132, '132212019', 'Senior AI Engineer [KION AI]', '\"МТС\", Работа в IT', NULL, 'https://hh.ru/vacancy/132212019', 'Как Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я заинтересован в вакансии Senior AI Инженера. Однако, мой основной стек отличается от указанного в вакансии. Я готов изучить Python, FastAPI и другие технологии, чтобы внести свой вклад в проект. Мой опыт работы с MongoDB и PostgreSQL может быть полезен в разработке бэкенда. Я готов обсудить возможность адаптации моих навыков к потребностям проекта.', 'applied', '2026-05-01 22:45:25'),
(133, '132469638', 'QA Automation Engineer (Middle/Senior)', 'ООО Кэтлоджик', NULL, 'https://rabota.by/vacancy/132469638', 'Имею опыт разработки на Node.js, JavaScript и TypeScript, а также опыт работы с фреймворками Vue 3, React, Nuxt.js и Next.js. Кроме того, знаком с базами данных MongoDB и PostgreSQL. Готов применить свои навыки в автоматическом тестировании и участвовать в разработке и поддержке фреймворка для автоматического тестирования на Node.js. Опыт работы с JavaScript и знание Cypress и Playwright позволят мне быстро влиться в команду и начать работать над задачами. Готов к удаленной работе и гибкому графику.', 'applied', '2026-05-01 22:54:13'),
(134, '132157018', 'Project Manager', 'ООО Софтнетикс', NULL, 'https://rabota.by/vacancy/132157018', 'Как опытный Frontend-разработчик с опытом работы со стеком Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии Project Manager в компании Softnetix. Однако, я заметил, что технический стек компании отличается от моего опыта. \n\nМогу ли я обсудить возможность адаптации к новому стеку и обучения на работе? Кроме того, я хотел бы узнать больше о процессе коммуникации между командами и о том, как компания поддерживает рост и развитие своих сотрудников.', 'applied', '2026-05-01 23:00:56'),
(135, '132466160', 'Middle Frontend разработчик (Angular)', 'ООО Модульные строительные системы', NULL, 'https://rabota.by/vacancy/132466160', 'Я - опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js. Однако, я готов изучить и освоить Angular 15+, а также другие необходимые технологии, такие как Ionic 7-8 и библиотеки для построения диаграмм и графов. Меня привлекает возможность работать над сложным и нагруженным проектом, который может улучшить качество жизни тысяч людей. Я готов работать в офисе в г. Минске и готов к обучению английскому языку за счет компании. Я уверен, что мой опыт и навыки будут полезны для вашей команды и готов обсудить возможность работы в \"CUBY Technologies\".', 'applied', '2026-05-01 23:08:44'),
(137, '131980337', 'FullStack - разработчик FastAPI / REACT, г.Минск', 'ОАО АСБ Беларусбанк', NULL, 'https://rabota.by/vacancy/131980337', 'Хотя мой основной стек - Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я готов изучить и освоить новые технологии, включая FastAPI и Python. Опыт работы с React и системами контроля версий Git (GitLab, GitHub) имеется. Готов обсудить возможность работы и условия оплаты труда.', 'applied', '2026-05-01 23:15:35'),
(138, '131647517', 'Middle Frontend Developer React (Ведущий инженер-программист)', 'Национальный центр электронных услуг,РУП', NULL, 'https://rabota.by/vacancy/131647517', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я уверен в своей способности разработать высоконагруженные приложения и интеграции с внешними системами. Мои знания HTML, CSS, JavaScript и TypeScript, а также опыт работы с REST API и WebSocket, позволяют мне эффективно решать задачи в области электронных услуг и электронного правительства. Я готов принять участие в полном цикле разработки продуктов и взаимодействовать с другими членами команды. Готов пройти тестовое задание и предварительное испытание.', 'applied', '2026-05-02 06:59:07'),
(140, '131978838', 'Программист JavaScript, Three.js', 'ООО Модульные строительные системы', NULL, 'https://rabota.by/vacancy/131978838', 'Как опытный Frontend-разработчик с опытом работы в Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен, что могу внести значительный вклад в разработку инновационной платформы для автоматизации строительства и управления недвижимостью. Однако, я не вижу прямого совпадения моего стека с требуемым в вакансии (JavaScript и Three.js). Если есть возможность расширить требования или рассмотреть кандидата с похожим опытом, я готов обсудить детали проекта и свою квалификацию.', 'applied', '2026-05-02 07:06:28'),
(141, '132319765', 'Referral Program Manager / Менеджер программ лояльности', 'Novakid Inc', NULL, 'https://hh.ru/vacancy/132319765', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен, что могу принести ценность в роль Менеджера по работе с реферальными проектами в Novakid School. Мои технические навыки и опыт работы с различными технологиями позволят мне эффективно общаться с разработчиками и дизайнерами, а также понимать технические требования проектов. Я готов принять вызов и внести свой вклад в успех вашей команды.', 'applied', '2026-05-02 07:16:04'),
(142, '132439251', 'Frontend-разработчик на React/ TypeScript, Головной офис, г. Минск', 'ОАО АСБ Беларусбанк', NULL, 'https://rabota.by/vacancy/132439251', 'Как опытный frontend-разработчик с опытом работы с React, TypeScript и Node.js, я уверен в своей способности работать со сложными табличными данными, интегрироваться с REST API и WebSockets, а также проектировать и валидировать многошаговые формы. Мой опыт работы с Vue 3, Nuxt.js и Next.js также позволяет мне гибко подходить к задачам. Я знаком с технологиями, перечисленными в требованиях, включая TanStack Query, Zustand, react-hook-form и Zod. Готов обсудить детали и возможности на собеседовании.', 'applied', '2026-05-02 07:20:45'),
(143, '132111330', 'Team Lead .Net', 'ООО Клеркгрупп', NULL, 'https://rabota.by/vacancy/132111330', 'Хотя мой основной стек включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен, что мой опыт и навыки в управлении командой и разработке могут быть адаптированы к технологиям .NET и другим инструментам, используемым в вашей компании. Я готов изучить новые технологии и внести свой вклад в успех вашей команды. Мой опыт в управлении командами и разработке может быть полезен для вашей компании, особенно в области планирования, декомпозиции задач и улучшения процессов разработки. Я заинтересован в обсуждении моей кандидатуры и изучении возможностей роста в вашей компании.', 'applied', '2026-05-02 07:26:41'),
(145, '132586790', 'Java developer (Middle/Senior)', 'IDF Technology', NULL, 'https://rabota.by/vacancy/132586790', 'К сожалению, моя специализация как Frontend-разработчика (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL) не соответствует требованиям вакансии Java developer. Я не имею необходимого опыта работы с Kotlin или Java, а также с брокерами сообщений и асинхронным межсервисным взаимодействием. Поэтому я не могу претендовать на эту вакансию.', 'applied', '2026-05-02 07:33:48'),
(146, '132585646', 'HTML верстальщик (Беларусь)', 'ООО Манао Дев', NULL, 'https://rabota.by/vacancy/132585646', 'Меня привлекает эта вакансия, потому что она предлагает широкий спектр задач, от адаптивной вёрстки до создания анимаций и слайдеров. С моим опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен, что могу внести значительный вклад в вашу команду. Готов обсудить детали на собеседовании. Telegram: @ваш_ник_телеграмма', 'applied', '2026-05-02 07:40:35'),
(147, '132551563', 'WP / Content Manager', 'ООО ЭйЧар Тим', NULL, 'https://rabota.by/vacancy/132551563', 'Как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я заинтересован в возможности применения своих навыков в контексте SEO-продвижения сайтов. Однако, я заметил, что вакансия контент-менеджера больше ориентирована на работу с контентом и SEO, чем на прямое программирование.\n\nЕсли я правильно понимаю, то компания ищет специалиста, который может работать с текстом, использовать инструменты для создания контента и имеет базовые знания о веб-технологиях. Хотя мой основной опыт лежит в области frontend-разработки, я готов учиться и развиваться в новой области.\n\nЯ бы хотел обсудить возможность применения моих навыков в контексте контент-менеджмента и SEO, а также узнать больше о процессе обучения и развития внутри компании.', 'applied', '2026-05-02 07:48:05'),
(148, '132545513', 'QA Engineer', 'ООО КодХаб', NULL, 'https://rabota.by/vacancy/132545513', 'Как Frontend-разработчик, я не подхожу под вакансию QA engineer. Однако, если в компании есть потребность в специалисте по разработке frontend, я готов предложить свои услуги. Мой стек включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL. Готов обсудить возможности сотрудничества.', 'applied', '2026-05-02 07:53:44'),
(149, '132544372', 'QA Automation инженер (Junior+/Middle)', 'ООО Клевер Системс', NULL, 'https://rabota.by/vacancy/132544372', 'К сожалению, мой основной стек технологий (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL) не соответствует требованиям вакансии Automation QA инженера, где необходимы знания C#, .NET и Playwright. Однако, я готов изучить новые технологии и расширить свои знания для работы в вашей команде. Меня привлекает гибкий график работы, возможность работать гибридно и медицинская страховка. Если вы ищете кандидата, готового учиться и развиваться, я готов обсудить возможность работы в вашей команде.', 'applied', '2026-05-02 07:59:13'),
(150, '132464769', 'Ведущий инженер-программист (Frontend Angular / Fullstack)', 'Информационно-издательский центр по налогам и сборам', NULL, 'https://rabota.by/vacancy/132464769', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я уверен в своей способности внести свой вклад в вашу команду. Однако, я заметил, что вакансия требует опыта работы с Angular 11+, который не входит в мой текущий стек. Несмотря на это, я готов изучить и освоить новые технологии, включая Angular, чтобы соответствовать требованиям вашей компании. Я также готов работать над задачами backend-части, когда нет задач по frontend-разработке. Моя доброжелательность, ответственность и self-менеджмент позволят мне быстро интегрироваться в вашу команду и эффективно работать над проектами. Я заинтересован в возможности работать в стабильной компании с позитивной командой профессионалов и готов обсудить детали моей кандидатуры.', 'applied', '2026-05-02 08:06:18'),
(151, '132459122', 'AI Product Engineer', 'ООО ВитАй Ворлд', NULL, 'https://rabota.by/vacancy/132459122', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я уверен в своей способности реализовывать AI-фичи и интегрировать LLM API. Мой опыт работы с MongoDB и PostgreSQL позволяет мне эффективно работать с данными. Я готов взять на себя роль AI Product Engineer и внести свой вклад в разработку цифровой инфраструктуры современного бизнеса.', 'applied', '2026-05-02 08:14:53'),
(152, '132458606', 'UX/UI Designer (Web / Mobile / SaaS)', 'ООО ВитАй Ворлд', NULL, 'https://rabota.by/vacancy/132458606', 'Как Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии UX/UI Designer в VitAi World. Однако, мой опыт больше связан с разработкой, чем с дизайном. Если вы открыты для кандидата с техническим опытом и желанием развиваться в области UX/UI-дизайна, я готов обсудить возможность работы в вашей команде.', 'applied', '2026-05-02 08:21:39'),
(153, '130767113', 'Middle Cocos разработчик', 'ООО Ридотто', NULL, 'https://rabota.by/vacancy/130767113', 'Хотя мой основной стек включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в расширении своих возможностей в области геймдева. Опыт работы с JavaScript и TypeScript может быть полезен в освоении Cocos Creator и разработке игр. Готов изучить новые технологии и внести свой вклад в проект То!Лото.', 'applied', '2026-05-02 08:28:07'),
(154, '132441082', 'Tech Lead / Full Stack Lead (MedusaJS, Node.js, React)', 'Itransition', NULL, 'https://rabota.by/vacancy/132441082', 'Как Tech Lead с 5+ годами опыта, я уверен в своей способности проектировать и вести разработку крупномасштабной платформы электронной коммерции и цифровой экосистемы на основе MedusaJS. Мой опыт работы с Node.js, React, Next.js и PostgreSQL позволяет мне эффективно решать сложные задачи. Я готов взять на себя ответственность за архитектуру и разработку платформы, а также наставлять и руководить командой разработчиков. Готов обсудить детали проекта и свою кандидатуру.', 'applied', '2026-05-02 08:36:28'),
(155, '132440119', 'Senior Java Developer', 'Digital Chief', NULL, 'https://hh.ru/vacancy/132440119', 'Извините, но кажется, что вакансия требует специалиста с опытом в Java Backend, тогда как мой стек технологий включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL. Я не соответствую требованиям этой вакансии.', 'applied', '2026-05-02 08:45:27'),
(156, '132435017', 'JavaScript (NetSuite) developer', 'ООО ВебиКо', NULL, 'https://rabota.by/vacancy/132435017', 'Как Frontend-разработчик с опытом работы в стеке Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я заинтересован в вакансии JavaScript-разработчика в вашей команде. Однако, мой опыт сосредоточен на frontend-разработке, а не на NetSuite или SuiteScript. Я готов изучить новые технологии и расширить свои навыки. Если вы ищете разработчика, готового учиться и адаптироваться, я готов обсудить возможность работы в вашей команде.', 'applied', '2026-05-02 08:52:46'),
(157, '132428784', 'Middle QA Manual Engineer', 'ООО БЛД Софт', NULL, 'https://rabota.by/vacancy/132428784', 'Как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии Middle QA Manual Engineer в компании БЛД Софт. Однако, я заметил, что моя основная специализация - разработка frontend-приложений, а не тестирование. Тем не менее, я готов изучить новые технологии и методы тестирования, и считаю, что мой опыт работы с frontend-технологиями может быть полезен при тестировании frontend-приложений на разных платформах. Я готов обсудить возможность моего участия в проекте и изучить требования к вакансии более подробно.', 'applied', '2026-05-02 08:57:21'),
(158, '132392342', 'Frontend разработчик', 'ООО Рэд', NULL, 'https://hh.ru/vacancy/132392342', 'Хотя мой основной стек включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я готов расширить свои знания и навыки в области разработки мобильных приложений на Flutter. Опыт работы с многими технологиями позволяет мне быстро адаптироваться к новым инструментам и технологиям. Заинтересован в возможности работать над мультиплатформенным мобильным приложением и интегрировать геопозиционирование, платежи и подписки. Готов изучить Flutter и внести свой вклад в разработку инновационных проектов.', 'applied', '2026-05-02 13:30:40'),
(159, '132377720', 'Content Manager (Spanish, English)', 'ООО Три Фаундэйшн', NULL, 'https://rabota.by/vacancy/132377720', 'Как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я не соответствую требованиям вакансии контент-менеджера. Однако, если компания ищет frontend-разработчика для поддержки маркетинговой команды, я готов обсудить возможности сотрудничества.', 'applied', '2026-05-02 13:35:29'),
(160, '132356814', 'Frontend Vibe Coder (React + Claude AI)', 'ООО Апп продакшн', NULL, 'https://rabota.by/vacancy/132356814', 'Как опытный Frontend-разработчик с опытом работы в Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен в своей способности внести значительный вклад в вашу команду. Я знаком с адаптивной вёрсткой, mobile-first подходом и глубоко понимаю нативный JavaScript. Я также имею опыт работы с UI-фреймворками и могу быстро адаптироваться к использованию Claude AI в разработке. Меня привлекает возможность работать в команде высоких профессионалов и участвовать в полном цикле создания и запуска успешных мобильных продуктов. Готов обсудить возможность сотрудничества.', 'applied', '2026-05-02 13:43:52'),
(161, '130652221', 'Product Designer', 'ООО Тогл Софт / Toggle', NULL, 'https://rabota.by/vacancy/130652221', 'К сожалению, вы не подходитесь для этой вакансии, поскольку она требует UX/UI-дизайнера, а ваш стек технологий ориентирован на frontend-разработку (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL).', 'applied', '2026-05-02 13:51:50'),
(163, '132302854', 'Senior Fullstack Engineer (Go/TypeScript)', 'ООО Фаброс', NULL, 'https://rabota.by/vacancy/132302854', 'Хотя мой основной стек — Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я уверен, что могу быстро освоить Go и другие необходимые технологии. С более чем 3-летним опытом коммерческой разработки, включая опыт работы с TypeScript и frontend-разработкой, я готов принять новые вызовы и внести свой вклад в ваш флагманский проект. Готов обсудить возможность трудоустройства и адаптации к вашей технологической экосистеме.', 'applied', '2026-05-02 13:59:30'),
(164, '132245362', 'Angular Engineer', 'ООО Орион Софт', NULL, 'https://rabota.by/vacancy/132245362', 'Хотя мой основной стек — Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я готов расширить свои знания и навыки в области Angular. С более чем 3-летним опытом коммерческой разработки и уверенным знанием TypeScript, я уверен, что могу быстро освоить Angular и внести значительный вклад в вашу команду. Кроме того, мой опыт работы с frontend-приложениями и их оптимизацией, а также знание принципов построения и интеграции с backend через REST API, могут быть полезны для вашей команды. Я готов учиться и расти, и я считаю, что мой универсальный подход и навыки могут быть ценными для вашей компании.', 'applied', '2026-05-02 14:06:13'),
(165, '132239507', 'Senior Salesforce Developer', 'Team.Inno / Фабрика инноваций и решений', NULL, 'https://rabota.by/vacancy/132239507', 'К сожалению, мой стек технологий (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL) не соответствует требованиям вакансии, ориентированной на Salesforce. Однако, если есть возможность изучения и работы с новыми технологиями, я готов рассмотреть возможность обучения и развития в направлении Salesforce. Мой опыт в frontend-разработке и знание JavaScript могут быть полезными в изучении Lightning Web Components (LWC) и других технологий Salesforce. Готов обсудить возможность обучения и дальнейшего сотрудничества.', 'applied', '2026-05-02 14:12:29'),
(166, '132233885', 'Back-end разработчик (Python / Django/FastAPI)', 'ООО Джей Эс Глобал', NULL, 'https://rabota.by/vacancy/132233885', 'К сожалению, моя специализация - Frontend-разработка с использованием Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL. Вакансия требует опытного Back-end разработчика Python с опытом работы на Django и FastAPI. Мой стек технологий не соответствует требованиям вакансии.', 'applied', '2026-05-02 14:18:44'),
(167, '132223391', 'Python Developer', 'Team.Inno / Фабрика инноваций и решений', NULL, 'https://rabota.by/vacancy/132223391', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в возможности присоединиться к команде Team.Inno. Однако, я заметил, что в описании вакансии упоминается опыт работы на Python, который не входит в мой текущий стек технологий. Я готов изучить новые технологии и расширить свои знания, но хотел бы обсудить возможность адаптации моих навыков к потребностям компании.', 'applied', '2026-05-02 14:23:53'),
(168, '132218869', 'Junior Frontend Developer (Angular)', 'Andersen', NULL, 'https://rabota.by/vacancy/132218869', 'Хотя у меня нет прямого опыта с Angular, мой опыт работы с Vue 3, React и другими frontend-фреймворками позволяет мне быстро адаптироваться к новым технологиям. Я уверен, что мои навыки в JavaScript, TypeScript и HTML/CSS, а также опыт работы с Node.js, MongoDB и PostgreSQL, будут полезны для вашего проекта. Я готов учиться и развиваться в направлении Angular, и я считаю, что моя универсальность и способность быстро адаптироваться будут ценным активом для вашей команды.', 'applied', '2026-05-02 14:31:48');
INSERT INTO `vacancies` (`id`, `hh_id`, `title`, `company`, `salary`, `url`, `cover_letter`, `status`, `created_at`) VALUES
(169, '132199525', 'Тестировщик (QA Engineer (Mobile & Web))', 'ООО Дизаркс', NULL, 'https://rabota.by/vacancy/132199525', 'Как Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии QA Engineer (Mobile & Web). Однако, я хочу отметить, что мой основной стек технологий не соответствует требованиям вакансии. Тем не менее, я готов изучить и освоить новые технологии, такие как Android Studio, Xcode и TestFlight, для того чтобы возглавить контроль качества продукта на стыке мобильных и веб-технологий. Мой аналитический склад ума, умение работать в команде и внимание к деталям могут быть полезными в этой роли. Готов обсудить возможность моего участия в проекте и изучения новых технологий.', 'applied', '2026-05-02 14:37:39'),
(170, '132190247', 'Fullstack Engineer (Python/Typescript)', 'Филиал Общества с ограниченной ответственностью Европейская металлургическая компания (Российская Федерация)', NULL, 'https://rabota.by/vacancy/132190247', 'Хотя мой основной стек включает в себя Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен в своей способности быстро адаптироваться к работе с Python и FastAPI на бэкенде, учитывая мой опыт с Node.js и JavaScript. Мой опыт с TypeScript и React/Next.js соответствует требованиям frontend-разработки. Кроме того, я имею опыт работы с SQL и NoSQL базами данных, что соответствует требованиям проектирования и развития БД. Я готов взять на себя ответственность за сервис, включая код, релизы, инциденты и сопровождение. Мне интересна возможность профессиональной самореализации и расширения в вашей компании.', 'applied', '2026-05-02 15:34:56'),
(171, '132176077', 'Frontend Developer', 'HRScan', NULL, 'https://hh.ru/vacancy/132176077', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен, что могу внести свой вклад в развитие вашей команды. Мои навыки включают разработку клиентской логики, создание компонентов, оптимизацию производительности и работу с API. Я знаком с современной CSS-архитектурой и адаптивностью, а также имею опыт работы с серверной частью и базами данных. Я готов использовать AI-инструменты для ускорения разработки и улучшения качества кода. Готов обсудить детали и возможности сотрудничества.', 'applied', '2026-05-02 15:40:16'),
(172, '132174781', 'Fullstack .NET Core / JS Software Engineer (Crafting, Growth, Real Products)', 'ООО Центория Софт', NULL, 'https://rabota.by/vacancy/132174781', 'В своей предыдущей роли я столкнулся с неожиданным багом, связанным с асинхронной обработкой запросов в приложении на Vue 3 и Node.js. Баг вызывал периодические сбои в работе системы, но не оставлял никаких явных следов в логах. После тщательного анализа кода и изучения поведения системы, я обнаружил, что проблема заключалась в неправильной реализации промисов, что приводило к утечке памяти. Для решения проблемы я реализовал корректную обработку асинхронных операций и добавил механизмы контроля памяти, что полностью решило проблему. Этот опыт научил меня тщательно проверять свою работу и не пренебрегать потенциальными последствиями своих решений.', 'applied', '2026-05-02 15:45:07'),
(178, '131265449', 'Бизнес-аналитик SAP BW/BI', 'ООО «СпроАйТи»', NULL, 'https://rabota.by/vacancy/131265449', 'К сожалению, моя квалификация не соответствует требованиям этой вакансии, поскольку мой опыт и навыки лежат в области frontend-разработки (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL), а не в области бизнес-аналитики SAP BW/BI.', 'applied', '2026-05-02 16:08:25'),
(179, '132111868', 'Senior Frontend Developer (Angular)', 'ООО Эффишентли ЕЕ', NULL, 'https://rabota.by/vacancy/132111868', 'Хотя моя основная специализация - Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, я заинтересован в возможности работать с Angular и GraphQL. Мой опыт работы с фронтенд-разработкой и знание принципов модульной архитектуры могут быть полезны для вашей команды. Готов обсудить возможность адаптации моих навыков к вашим требованиям и изучить новые технологии.', 'applied', '2026-05-02 16:15:28'),
(180, '132087733', 'UI/UX Designer (Fintech)', 'ООО ЛВО Интернешнл', NULL, 'https://rabota.by/vacancy/132087733', 'К сожалению, моя специализация как Frontend-разработчика (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL) не соответствует требованиям вакансии UI/UX Designer. Однако, если у вас есть возможность рассмотреть кандидата с опытом frontend-разработки для другой роли или сотрудничества, я готов обсудить возможности.', 'applied', '2026-05-02 16:24:14'),
(181, '131241344', 'Старший системный аналитик (Телеком, NMS)', 'ЗАО Инженерный Центр Ядро', NULL, 'https://rabota.by/vacancy/131241344', 'Как Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии Ведущего системного аналитика в компании YADRO. Однако, я заметил, что требуемый стек технологий включает Go, Микросервисы, Kubernetes и Angular, который отличается от моего текущего стека.\n\nНесмотря на это, я уверен в своих аналитических навыках и способности быстро адаптироваться к новым технологиям. Я готов пройти тренинги и получить необходимые знания для работы в компании. Мой опыт работы с frontend-фреймворками и базами данных может быть полезен в анализе и разработке требований для системы NMS.\n\nЯ бы хотел обсудить возможность моей кандидатуры и узнать больше о процессе адаптации и тренингов, которые компания предлагает.', 'applied', '2026-05-02 16:32:32'),
(182, '131581944', 'Дежурный системный администратор Linux (Junior)', 'IDF Technology', NULL, 'https://rabota.by/vacancy/131581944', 'К сожалению, вакансия не соответствует моей профессии Frontend-разработчика. Вакансия требует опытного системного администратора, тогда как мой опыт и навыки лежат в области frontend-разработки с использованием Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL. Если у вас есть вакансии, связанные с frontend-разработкой, я был бы рад обсудить возможности сотрудничества.', 'applied', '2026-05-02 16:38:26'),
(183, '132071866', 'PHP-программист/программист CMS 1C-Bitrix/Full stack WEB-developer', 'ИП Шингирей Анна Андреевна', NULL, 'https://rabota.by/vacancy/132071866', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я заинтересован в вакансии программиста в вашей студии. Однако, я заметил, что требуемые технологии (1C-Bitrix, PHP, CMS Wordpress) не полностью соответствуют моему стеку. Тем не менее, я готов изучить новые технологии и расширить свои знания. Я ценю гибкий график, удаленную работу и возможность карьерного роста. Готов обсудить зарплату и условия работы.', 'applied', '2026-05-02 16:47:16'),
(184, '132033951', 'Middle Python Developer', 'ООО Хьюман Аппс/ Human Apps', NULL, 'https://rabota.by/vacancy/132033951', 'Как Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я заинтересован в вакансии Backend-разработчика, поскольку она предлагает возможность расширить мои навыки и опыт в области Backend-разработки. Однако, я заметил, что моя основная специализация лежит в области Frontend-разработки, и я не имею прямого опыта работы с Python, FastAPI и некоторыми другими технологиями, указанными в вакансии.\n\nТем не менее, я готов учиться и развивать новые навыки, и я считаю, что мой опыт работы с Node.js, JS и TS может быть полезен в контексте Backend-разработки. Кроме того, я знаком с концепциями RESTful API и GraphQL, и я имею опыт работы с MongoDB и PostgreSQL.\n\nЯ бы хотел обсудить возможность моего участия в проекте и то, как я могу внести свой вклад в развитие продукта. Я готов учиться и адаптироваться к новым технологиям и инструментам, и я считаю, что моя страсть к разработке и моя способность быстро учиться могут быть ценными активами для вашей команды.', 'applied', '2026-05-02 16:52:03'),
(185, '132032832', 'E-commerce Director /Руководитель е-сom направления', 'ООО Трансторгбизнес', NULL, 'https://rabota.by/vacancy/132032832', 'Как frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я заинтересован в вакансии по управлению онлайн-продажами в ТрансТоргБизнес. Мои навыки в области frontend и опыт работы с MongoDB и PostgreSQL могут быть полезны для улучшения функционала сайтов. Я готов применить свои знания для оптимизации конверсии, маркетинговых кампаний и логистики, а также для разработки и реализации стратегий интернет-маркетинга. Мои коммуникативные навыки и умение анализировать данные могут помочь в управлении командой и принятии решений на основе метрик.', 'applied', '2026-05-02 17:00:18'),
(186, '132028287', 'Frontend-разработчик', 'ООО Апп продакшн', NULL, 'https://rabota.by/vacancy/132028287', 'Я готов внести свой вклад в вашу Frontend-команду, используя мой опыт работы с React, Node.js, JS и TS. Опыт работы с Vue 3, Nuxt.js и Next.js также может быть полезен для разработки адаптивной верстки и веб-приложений. Я готов принять челендж и развиваться вместе с компанией.', 'applied', '2026-05-02 17:08:31'),
(187, '130602052', 'Преподаватель Roblox и Python в онлайн-школу программирования', 'IT школа Hello World', NULL, 'https://hh.ru/vacancy/130602052', 'Как опытный Frontend-разработчик с опытом работы с Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js, я готов преподавать Frontend в вашей онлайн-школе. Готовность работать минимум 25 часов в неделю, наличие необходимого оборудования и стабильного интернета. Хочу поделиться знаниями и вдохновить детей на изучение программирования. Откликаюсь на вакансию и готов пройти все этапы отбора.', 'applied', '2026-05-02 17:15:04'),
(188, '130102864', 'ABAP-разработчик', 'ООО «СпроАйТи»', NULL, 'https://rabota.by/vacancy/130102864', 'К сожалению, моя квалификация не соответствует требованиям вакансии ABAP-разработчика. Мой стек технологий включает Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL. Я готов рассмотреть другие возможности, соответствующие моим навыкам.', 'applied', '2026-05-02 17:20:38'),
(189, '131988743', 'Frontend Developer (Angular /React / Next.js)', 'ООО ЛВО Интернешнл', NULL, 'https://rabota.by/vacancy/131988743', 'Как опытный Frontend-разработчик с опытом работы в Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен в своей способности внести значительный вклад в вашу команду. Мой опыт работы с современными фронтенд-технологиями и знание принципов работы виртуального DOM, жизненного цикла компонентов и Redux, позволяет мне эффективно решать задачи и оптимизировать приложения. Я готов использовать современные AI-инструменты для ускорения разработки и улучшения качества кода.', 'applied', '2026-05-02 17:26:02'),
(190, '131984605', 'Dart / Flutter разработчик (frontend)', 'ООО Целевое управление', NULL, 'https://hh.ru/vacancy/131984605', 'Дарт/Флуттер не входит в мой стек, но я готов изучить и освоить новые технологии. Обладаю опытом разработки кроссплатформенных приложений с использованием Vue 3, React, Node.js, JS, TS, Nuxt.js и Next.js. Также имею опыт работы с базами данных MongoDB и PostgreSQL. Готов работать удаленно и сотрудничать на долгосрочной основе.', 'applied', '2026-05-02 17:34:05'),
(191, '131055202', 'QA-инженер — Frontend', 'Т-Банк. ИТ. QA', NULL, 'https://hh.ru/vacancy/131055202', 'Как опытный Frontend-разработчик с опытом работы в технологиях Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я уверен в своей способности проводить функциональное и автоматизированное тестирование веб-приложений. Мой опыт работы с DevTools, системами логирования и кросс-браузерным тестированием верстки будет полезен для вашей команды. Я готов работать в продуктовой команде в рамках Agile-процессов и разрабатывать тестовую документацию для проектов. Мои знания SQL и принципы работы реляционных СУБД также будут полезны. Я заинтересован в возможности работать в Т-Банке и внести свой вклад в создание высококачественных продуктов.', 'applied', '2026-05-02 17:37:51'),
(192, '131909486', 'Frontend-разработчик — React', 'Т-Банк. ИТ. Разработка', NULL, 'https://hh.ru/vacancy/131909486', 'Имею опыт работы с React, Node.js, JavaScript и TypeScript. Также знаком с CI/CD и unit-тестами. Готов работать в распределенной команде и внедрять новые технологии. Заинтересован в развитии продуктов и инструментов, а также в участии в жизни фронтенд-сообщества. Готов обсудить зарплату и условия работы на собеседовании.', 'applied', '2026-05-02 17:44:26'),
(193, '131909437', 'Frontend разработчик Angular', 'Т-Банк. ИТ. Разработка', NULL, 'https://hh.ru/vacancy/131909437', 'Хотя мой основной стек — Vue 3, React и Node.js, я готов изучить и освоить Angular, чтобы присоединиться к вашей команде. С более чем 3-летним опытом коммерческой разработки и знанием JavaScript, я уверен, что смогу быстро адаптироваться и внести свой вклад в проекты Т-Банка. Мне интересно участвовать в разработке SPA-приложений и вносить свой вклад в опенсорс-проекты. Давайте обсудим возможность моего присоединения к команде и обсудим детали на собеседовании.', 'applied', '2026-05-02 17:53:00'),
(194, '131508597', 'PHP Developer', 'ООО Розум Системс', NULL, 'https://rabota.by/vacancy/131508597', 'Я — опытный Frontend-разработчик со стопкой Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js. Также имею опыт работы с MongoDB и PostgreSQL. Однако, заметил, что вакансия требует PHP-разработчика. Хотя мой основной стек не соответствует требованиям, я готов изучать новые технологии и применять их на практике. Если компания готова рассмотреть кандидата с потенциалом роста и готовностью изучать PHP, я был бы рад обсудить возможность работы в вашей команде.', 'applied', '2026-05-02 18:01:04'),
(196, '131858873', 'Full Stack Developer (.NET+Angular)', 'Andersen', NULL, 'https://rabota.by/vacancy/131858873', 'К сожалению, моя специализация как Frontend-разработчика (Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js) не соответствует требованиям вакансии, ориентированной на технологический стек .NET и Angular. Однако, если Andersen рассматривает возможность расширения технологического спектра или имеет другие подходящие вакансии, я был бы рад обсудить возможности сотрудничества.', 'applied', '2026-05-02 18:35:18'),
(197, '131851774', 'Разработчик Python в LLM Platform', 'Т-Банк. ИТ. Разработка', NULL, 'https://hh.ru/vacancy/131851774', 'Как frontend-разработчик с опытом работы в стеке Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB и PostgreSQL, я заинтересован в вакансии LLM Platform. Однако, заметил, что требования включают опыт работы с Python 3, FastAPI и базами данных PostgreSQL, что не соответствует моему основному стеку. \n\nЕсли команда готова рассмотреть кандидата с другим технологическим стеком и готовность учиться и адаптироваться, я готов обсудить возможность работы в вашей команде. Мой опыт работы с frontend-технологиями и знание принципов разработки приложений может быть полезным в интеграции моделей в удобные для сотрудников интерфейсы.', 'applied', '2026-05-02 18:58:22'),
(198, '131832583', 'Senior Full Stack .NET developer', 'Promomash', NULL, 'https://hh.ru/vacancy/131832583', 'Как senior-разработчик с опытом в JavaScript и TypeScript, я заинтересован в роли Senior Full Stack .NET Developer в Promomash. Однако, мой основной стек — Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL, что отличается от требуемого стека .NET, C# и Angular. Я готов изучить новые технологии и применить свои навыки в новой области. Мой опыт работы с frontend и backend, а также знание принципов проектирования распределённых систем могут быть полезны в этой роли. Я готов обсудить возможность обучения и адаптации к новому стеку.', 'applied', '2026-05-02 19:00:28'),
(199, '132201603', 'Product Analyst (Event Analytics)', 'Genesis Group AG', NULL, 'https://hh.ru/vacancy/132201603', 'Я — опытный Frontend-разработчик с опытом работы в стеке Vue 3, React, Node.js, JS, TS, Nuxt.js, Next.js, MongoDB, PostgreSQL. Однако, кажется, что вакансия требует Product Analyst с опытом работы в Google Analytics, Google Tag Manager и SQL. Если есть возможность применения frontend-навыков в этой роли или возможность роста в компании, я готов обсудить возможность сотрудничества.', 'applied', '2026-05-02 19:05:23'),
(200, '132024029', 'Frontend-разработчик (финтех-проект)', 'Up pashkevich', NULL, 'https://hh.ru/vacancy/132024029', 'Имею опыт коммерческой разработки более 3 лет, владею JavaScript/TypeScript, React, Next.js. Опыт работы с REST, WebSocket, JWT/OAuth. Умею писать аккуратный, читаемый код и работать с Git. Готов влиять на продукт от идеи до релиза. Интересуют финтех и крипта, готов работать над инновационной платформой. Доступен для удаленной работы. Жду обсуждения деталей.', 'applied', '2026-05-02 19:10:13'),
(203, '132214637', 'Gameplay Developer (Python/C++)', 'Леста Игры', NULL, 'https://hh.ru/vacancy/132214637', NULL, 'new', '2026-05-02 21:40:43'),
