INSERT INTO `vacancies` (`id`, `hh_id`, `title`, `company`, `salary`, `url`, `cover_letter`, `status`, `created_at`) VALUES
(614, '135928703', 'Senior Fullstack Engineer (Go/TypeScript)', 'ООО Фаброс', NULL, 'https://brest.rabota.by/vacancy/135928703', 'I’m a motivated Frontend developer with approximately one year of hands-on experience building responsive interfaces using Vue 3, React, TypeScript, Nuxt.js, Next.js, and MongoDB. I’ve completed several educational projects focused on clean code, API integration, and performance optimization. I’m eager to transition into a Fullstack role, quickly learn Go and backend systems, and contribute to your team with clean, maintainable code and a strong commitment to growth.', 'applied', '2026-08-14 17:53:31'),
(615, '135928681', 'Senior Fullstack Engineer (PHP/Typescript)', 'ООО Фаброс', NULL, 'https://brest.rabota.by/vacancy/135928681', 'Junior Frontend Developer with practical experience in Vue 3, React, TypeScript, and modern stacks (Nuxt.js, Next.js). Built personal projects emphasizing clean code, type safety, and responsive interfaces. Eager to expand into full-stack development, rapidly adopt new tools, and contribute to team productivity. Quick learner committed to writing maintainable, test-ready code.', 'applied', '2026-08-14 17:57:23'),
